#!/usr/bin/env node
// Deterministic JS→Go conformance fixtures for encodeStateVectorFromUpdate.
//
// yjs counts a client only from clock 0: it takes the end of the client's
// structs up to the first Skip, gives no entry to a client whose first struct
// starts above 0, and writes clients in the update's order. Each row is a
// well-formed yjs update (V1 and V2) with the state vector yjs reads from it.
//
// Determinism: pinned clientIDs, canonical JSON, trailing newline.
// Regenerated by `make fixtures`; CI's drift gate diffs the result.
const Y = require('yjs')
const fs = require('fs')
const path = require('path')
const assert = require('assert')

const outDir = path.join(__dirname, '..', 'crdt', 'testdata')
const hex = (u8) => Buffer.from(u8).toString('hex')

function peer (client, gc = true) {
	const d = new Y.Doc({ gc })
	d.clientID = client
	return d
}

// sync sends each peer what it lacks from the others.
function sync (...docs) {
	for (const a of docs) {
		for (const b of docs) {
			if (a !== b) Y.applyUpdate(b, Y.encodeStateAsUpdate(a, Y.encodeStateVector(b)))
		}
	}
}

const rows = []
function row (name, v1, v2) {
	const sv = Y.encodeStateVectorFromUpdate(v1)
	const svV2 = Y.encodeStateVectorFromUpdateV2(v2)
	assert.deepStrictEqual(svV2, sv, name + ': V2 must match V1')
	rows.push({ name, v1: hex(v1), v2: hex(v2), sv: hex(sv) })
}
const rowV1 = (name, v1) => row(name, v1, Y.convertUpdateFormatV1ToV2(v1))
const holds = (v1, T) => Y.decodeUpdate(v1).structs.some((s) => s instanceof T)

// Three peers edit text, an array and a map; each local transaction's update is kept.
const docs = [peer(1), peer(300), peer(70000)]
const updates = new Map(docs.map((d) => [d, []]))
for (const d of docs) d.on('update', (u, _origin, _doc, tr) => { if (tr.local) updates.get(d).push(u) })
docs[0].getText('t').insert(0, 'hello')
docs[1].getArray('a').insert(0, [1, 2, 3])
sync(...docs)
const mid = Y.encodeStateVector(docs[2])
docs[0].getText('t').insert(5, ' world')
docs[1].getText('t').delete(0, 2)
// Replacing a nested map makes yjs collect its children into GC structs.
const nested = new Y.Map()
nested.set('n', 1)
docs[2].getMap('m').set('k', nested)
docs[2].getMap('m').set('k', 'w')
docs[2].getMap('m').set('j', 'z')
sync(...docs)
docs[1].getArray('a').insert(1, ['x'])
const [a, b] = docs
assert(holds(Y.encodeStateAsUpdate(a), Y.GC), 'a holds GC structs')

row('empty', Y.encodeStateAsUpdate(new Y.Doc()), Y.encodeStateAsUpdateV2(new Y.Doc()))
row('full state, three clients', Y.encodeStateAsUpdate(b), Y.encodeStateAsUpdateV2(b))
row('full state, GC structs', Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdateV2(a))
row('diff from a state vector', Y.encodeStateAsUpdate(b, mid), Y.encodeStateAsUpdateV2(b, mid))
rowV1('diffUpdate from a state vector', Y.diffUpdate(Y.encodeStateAsUpdate(b), mid))
rowV1('one transaction past clock 0', updates.get(a)[1])

// Merging non-adjacent transactions leaves a Skip where the missing one was.
const typist = peer(9)
const typed = []
typist.on('update', (u) => typed.push(u))
for (const ch of 'abc') typist.getText('t').insert(typist.getText('t').length, ch)
const skipAfterZero = Y.mergeUpdates([typed[0], typed[2]])
assert(holds(skipAfterZero, Y.Skip), 'merge holds a Skip')
rowV1('merge with a Skip after clock 0', skipAfterZero)
rowV1('merge of later transactions', Y.mergeUpdates(typed.slice(1)))

// Client 1 gives only its second transaction, and client 70000 leaves out its
// middle one, which the merge writes as a Skip.
const [ua, ub, uc] = docs.map((d) => updates.get(d))
const picked = [ua[1], ub[0], ub[2], uc[0], uc[2]]
const acrossClients = Y.mergeUpdates(picked)
assert(holds(acrossClients, Y.Skip), 'merge across clients holds a Skip')
row('merge across clients with Skips', acrossClients, Y.mergeUpdatesV2(picked.map((u) => Y.convertUpdateFormatV1ToV2(u))))

// Without GC, deleted content stays as items rather than GC structs.
const keep = peer(9, false)
keep.getText('t').insert(0, 'abc')
const keepSV = Y.encodeStateVector(keep)
keep.getText('t').delete(1, 1)
keep.getText('t').insert(2, 'de')
row('no GC, full state', Y.encodeStateAsUpdate(keep), Y.encodeStateAsUpdateV2(keep))
row('no GC, diff from a state vector', Y.encodeStateAsUpdate(keep, keepSV), Y.encodeStateAsUpdateV2(keep, keepSV))

// Hand-written updates: one client in two groups in a row, which yjs counts
// as one run, and a Skip of length zero, which ends the run as a longer one does.
const fromHex = (s) => new Uint8Array(Buffer.from(s, 'hex'))
rowV1('one client in two groups in a row', fromHex('02010900040101740161010901840900016200'))
rowV1('a zero-length Skip', fromHex('010309000401017401610a00840900016200'))

// yjs reads the state vector from the structs alone, so an update cut before
// its delete set still gives one.
const cut = (u) => {
	assert.strictEqual(u[u.length - 1], 0, 'the update ends with an empty delete set')
	return u.slice(0, -1)
}
row('no delete set', cut(Y.encodeStateAsUpdate(typist)), cut(Y.encodeStateAsUpdateV2(typist)))

const file = path.join(outDir, 'svfromupdate_yjs_fixtures.json')
fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n')
console.log(`wrote crdt/testdata/svfromupdate_yjs_fixtures.json (${rows.length} scenarios)`)
